SELECT ?point ?type ?zone ?tsid WHERE {
  ?point a brick:Sensor ;
        brick:hasProperty ?prop ;
        ref:hasTimeseriesId ?tsid .
  FILTER (?prop = brick:Temperature OR ?prop = "coolingSetpoint" || ?prop = "CoolingSetpoint")
}
LIMIT 40

SELECT ?point (STR(?type) AS ?type) (STR(?prop) AS ?prop) (STR(?tsid) AS ?tsid) WHERE {
  ?point a brick:Sensor ;
        brick:hasProperty ?prop .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
}
LIMIT 200

